mapper.select:
SELECT  

    AND w.work_order_id = #{id}
    AND w.production_plan_id = #{planId}
    AND (LOCATE(#{keyword}, i.item_code) > 0 OR LOCATE(#{keyword}, i.item_name) > 0)
    AND w.status = #{status}
 ORDER BY w.work_order_id DESC

SELECT p.production_plan_id, p.product_item_id, p.planned_qty, p.planned_date,
       i.item_code AS product_code, i.item_name AS product_name, i.unit_code
FROM production_plan p JOIN item i ON i.item_id = p.product_item_id WHERE p.production_plan_id = #{planId}

SELECT COUNT(p.production_result_id) AS result_count, COALESCE(SUM(p.produced_qty),0) AS produced_qty,
       COALESCE(SUM(p.good_qty),0) AS good_qty, COALESCE(SUM(p.defect_qty),0) AS defect_qty
FROM finished_goods_lot f JOIN production_result p ON p.finished_lot_id=f.finished_lot_id WHERE f.work_order_id=#{id}
